insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-184', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'To deposit 0.216 g of Ag (Ag = 108) from AgNO$_3$ at 0.50 A, the time required is', '["386 s","193 s","965 s","1930 s"]'::jsonb, 0, '$Q = m \times F / M = 0.216 \times 96500 / 108 = 193\ \mathrm{C}$; $t = Q/I = 193/0.50 = 386\ \mathrm{s}$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'electrolysis-faraday') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
