insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-185', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'The same charge that deposits 1.08 g of silver will deposit, from Cu$^{2+}$ (Cu = 63.5), a copper mass of', '["$0.318\\ \\mathrm{g}$","$1.08\\ \\mathrm{g}$","$0.635\\ \\mathrm{g}$","$2.16\\ \\mathrm{g}$"]'::jsonb, 0, 'Equivalents: $E(\mathrm{Ag}) = 108$, $E(\mathrm{Cu}) = 31.75$. $m_{\mathrm{Cu}} = 1.08 \times 31.75/108 = 0.318\ \mathrm{g}$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'electrolysis-faraday') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
