insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-188', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'The same current flows for the same time through AgNO$_3$ and then, separately, through AuCl$_3$ (Au = 197). If 1.08 g Ag is deposited, the gold deposited is nearest', '["$0.657\\ \\mathrm{g}$","$1.97\\ \\mathrm{g}$","$0.328\\ \\mathrm{g}$","$3.00\\ \\mathrm{g}$"]'::jsonb, 0, 'Equal charge means equal equivalents: $m_{\mathrm{Au}}/m_{\mathrm{Ag}} = (197/3)/108$, so $m_{\mathrm{Au}} = 1.08 \times 197/(3 \times 108) = 0.657\ \mathrm{g}$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'hard', 'electrolysis-faraday') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
